      \u0275\u0275elementStart(366, "h3", 22);
      \u0275\u0275text(367, "How AIDA generates new URLs");
      \u0275\u0275elementEnd();
      \u0275\u0275elementStart(368, "p");
      \u0275\u0275text(369, "For new pages, AIDA will use the H1 to generate a URL by doing the following:");
      \u0275\u0275elementEnd();
      \u0275\u0275elementStart(370, "ul")(371, "li");
      \u0275\u0275text(372, "remove accents");
      \u0275\u0275elementEnd();
      \u0275\u0275elementStart(373, "li");
      \u0275\u0275text(374, "remove punctuation (except periods or hyphens)");
      \u0275\u0275elementEnd();
      \u0275\u0275elementStart(375, "li");
      \u0275\u0275text(376, "convert everything to lowercase");
      \u0275\u0275elementEnd();
      \u0275\u0275elementStart(377, "li");
      \u0275\u0275text(378, "remove any small words from the English and French lists below");
      \u0275\u0275elementEnd();
      \u0275\u0275elementStart(379, "li");
      \u0275\u0275text(380, "convert spaces to hyphens");
      \u0275\u0275elementEnd()();
      \u0275\u0275elementStart(381, "p");
      \u0275\u0275text(382, "AIDA will continue to keep your new page url in sync with your H1 up until you make a deliberate change to the url or until it detects the page is no longer a 404.");
      \u0275\u0275elementEnd();
      \u0275\u0275elementStart(383, "p");
      \u0275\u0275text(384, "If any small words are missing from these lists, please let us know.");
